-size:40px}\n.card[data-size=\"6x3\"] .btns{grid-template-rows:minmax(0,1fr) minmax(0,1fr);min-height:0}\n.card[data-size=\"6x3\"] .act{min-height:0}\n\n/* 194x404 */\n.card[data-size=\"3x6\"] .baby{padding:8px;gap:6px}\n.card[data-size=\"3x6\"] .last{padding:4px 10px 6px;border-radius:16px}\n.card[data-size=\"3x6\"] .k{display:none}\n.card[data-size=\"3x6\"] .undo{min-height:30px;padding:0 10px;font-size:12px}\n.card[data-size=\"3x6\"] .last-main .ic{font-size:18px}\n.card[data-size=\"3x6\"] .last-main .nm{font-size:16px}\n.card[data-size=\"3x6\"] .last-main .tm{font-size:24px}\n.card[data-size=\"3x6\"] .btns{gap:6px;grid-template-rows:60px 60px}\n.card[data-size=\"3x6\"] .act{min-height:0}\n.card[data-size=\"3x6\"] .act .ic{font-size:24px}\n.card[data-size=\"3x6\"] .act .lb{font-size:15px}\n.card[data-size=\"3x6\"] .cell b{font-size:13px}\n.card[data-size=\"3x6\"] .cell span{font-size:10.5px}\n\n/* 404x404 */\n.card[data-size=\"6x6\"] .last-main .ic{font-size:30px}\n.card[data-size=\"6x6\"] .last-main .nm{font-size:22px}\n.card[data-size=\"6x6\"] .last-main .tm{font-size:44px}\n.card[data-size=\"6x6\"] .btns{grid-template-columns:repeat(4,minmax(0,1fr));grid-template-rows:96px}\n.card[data-size=\"6x6\"] .act{min-height:0}\n.card[data-size=\"6x6\"] .act .ic{font-size:30px}\n.card[data-size=\"6x6\"] .act .lb{font-size:15px}\n.card[data-size=\"6x6\"] .cell{flex-direction:row-reverse;gap:6px;padding:5px 4px}\n.card[data-size=\"6x6\"] .cell b{font-size:15px}\n.card[data-size=\"6x6\"] .cell span{font-size:12px}\n";
var TYPES={feed:{name:'喝奶',icon:'🍼'},sleep:{name:'入睡',icon:'🌙'},wake:{name:'睡醒',icon:'☀️'},diaper:{name:'换尿布',icon:'🧷'}};
var ORDER=['feed','sleep','wake','diaper'];
function p2(n){return n<10?'0'+n:''+n}
function fmtTime(ts){var d=new Date(ts);return p2(d.getHours())+':'+p2(d.getMinutes())}
function dayStart(ts){var d=new Date(ts);return new Date(d.getFullYear(),d.getMonth(),d.getDate()).getTime()}
function dayLabel(ts,now){
  var diff=Math.round((dayStart(now)-dayStart(ts))/86400000);
  if(diff===0)return '今天';
  if(diff===1)return '昨天';
  var d=new Date(ts);
  return (d.getMonth()+1)+'月'+d.getDate()+'日';
}
function fmtDur(ms){
  var m=Math.max(0,Math.floor(ms/60000));
  if(m<60)return m+'分钟';
  var h=Math.floor(m/60),r=m%60;
  if(h>=24){var dd=Math.floor(h/24),hh=h%24;return dd+'天'+(hh?hh+'小时':'')}
  return r?h+'小时'+r+'分钟':h+'小时';
}
function fmtAgo(ms){
  if(ms<60000)return '刚刚';
  return fmtDur(ms)+'前';
}
function fmtShort(ms){
  var m=Math.max(0,Math.round(ms/60000));
  var h=Math.floor(m/60),r=m%60;
  if(!h)return r+'m';
  return h+'h'+(r?r+'m':'');
}
function getLogs(s){
  var arr=Array.isArray(s&&s.logs)?s.logs:[];
  return arr.filter(function(l){return l&&l.id&&TYPES[l.type]&&typeof l.ts==='number'})
    .slice().sort(function(a,b){return a.ts-b.ts});
}
function lastSleepEvent(logs){
  for(var i=logs.length-1;i>=0;i--){
    if(logs[i].type==='sleep'||logs[i].type==='wake')return logs[i];
  }
  return null;
}
function overlap(a,b,lo,hi){
  return Math.max(0,Math.min(b,hi)-Math.max(a,lo));
}
function sleepToday(logs,now){
  var start=dayStart(now),total=0,begin=null;
  for(var i=0;i<logs.length;i++){
    var l=logs[i];
    if(l.type==='sleep'){if(begin===null)begin=l.ts}
    else if(l.type==='wake'&&begin!==null){total+=overlap(begin,l.ts,start,now);begin=null}
  }
  if(begin!==null)total+=overlap(begin,now,start,now);
  return total;
}
function countToday(logs,now,type){
  var start=dayStart(now),n=0;
  for(var i=0;i<logs.length;i++){
    if(logs[i].type===type&&logs[i].ts>=start)n++;
  }
  return n;
}

function mount(ctx){
  const {root,el,state,ui,update,redraw,uid,size}=ctx;
  const now=Date.now();
  const logs=getLogs(state);
  const last=logs.length?logs[logs.length-1]:null;
  const lastSE=lastSleepEvent(logs);
  const inline=size==='3x6'||size==='6x6';
  const pop=!!ui.pop;
  ui.pop=false;

  function fail(){ui.err='保存失败，请重试';ui.pop=false;redraw()}
  function add(type){
    ui.err='';ui.pop=true;ui.delId='';
    update(function(s){
      const arr=Array.isArray(s.logs)?s.logs:[];
      return {...s,logs:arr.concat([{id:uid(),type:type,ts:Date.now()}])};
    }).catch(fail);
  }
  function remove(id){
    ui.err='';ui.delId='';ui.pop=false;
    update(function(s){
      const arr=Array.isArray(s.logs)?s.logs:[];
      return {...s,logs:arr.filter(function(l){return l.id!==id})};
    }).catch(fail);
  }
  function openHist(){ui.view='history';redraw()}
  function closeHist(){ui.view='';ui.delId='';redraw()}

  function row(l){
    const t=TYPES[l.type];
    const ask=ui.delId===l.id;
    return el('div',{class:'row'},
      el('span',{class:'ic','aria-hidden':'true'},t.icon),
      el('span',{class:'nm'},t.name),
      el('span',{class:'tm'},fmtTime(l.ts)),
      el('button',{type:'button',class:'del'+(ask?' ask':''),
        'aria-label':(ask?'确认删除':'删除')+t.name+' '+fmtTime(l.ts),
        onclick:function(){
          if(ask){remove(l.id)}else{ui.delId=l.id;redraw()}
        }},ask?'删除?':'×'));
  }
  function histList(){
    const box=el('div',{class:'hist'});
    if(!logs.length){
      box.append(el('div',{class:'empty'},'还没有记录，点下面的按钮就会记下现在的时间'));
      return box;
    }
    let cur=-1;
    for(let i=logs.length-1;i>=0;i--){
      const l=logs[i];
      const key=dayStart(l.ts);
      if(key!==cur){cur=key;box.append(el('div',{class:'dayh'},dayLabel(l.ts,now)))}
      box.append(row(l));
    }
    return box;
  }
  function summary(){
    function cell(v,k){return el('div',{class:'cell'},el('b',{},v),el('span',{},k))}
    return el('div',{class:'sum'},
      cell(countToday(logs,now,'feed')+'次','今日喝奶'),
      cell(countToday(logs,now,'diaper')+'次','今日尿布'),
      cell(fmtShort(sleepToday(logs,now)),'今日睡眠'));
  }


  function statusText(){
    if(!lastSE)return '';
    const d=fmtDur(Date.now()-lastSE.ts);
    return lastSE.type==='sleep'?'睡着中 · 已睡 '+d:'醒着 · 已醒 '+d;
  }
  const agoEl=el('span',{class:'ago'+(ui.err?' err':'')},ui.err?'⚠ '+ui.err:(last?fmtAgo(now-last.ts):''));
  const stEl=el('div',{class:'last-sub'},statusText());

  function lastBlock(){
    const head=el('div',{class:'last-head'},
      el('span',{class:'k'},'最近一次'),
      agoEl,
      el('button',{type:'button',class:'undo',disabled:!last,
        'aria-label':last?'撤回'+TYPES[last.type].name+' '+fmtTime(last.ts):'没有可撤回的记录',
        onclick:function(){if(last)remove(last.id)}},'↶ 撤回'));
    let main;
    if(last){
      const t=TYPES[last.type];
      const today=dayStart(last.ts)===dayStart(now);
      const kids=[
        el('span',{class:'ic','aria-hidden':'true'},t.icon),
        el('span',{class:'nm'},t.name),
        el('span',{class:'dl'},today?'':dayLabel(last.ts,now)),
        el('span',{class:'tm'},fmtTime(last.ts))
      ];
      if(inline){
        main=el('div',{class:'last-main'},...kids);
      }else{
        kids.push(el('span',{class:'go','aria-hidden':'true'},'›'));
        main=el('button',{type:'button',class:'last-main','aria-label':'查看全部记录',onclick:openHist},...kids);
      }
    }else{
      main=el('div',{class:'last-main'},
        el('span',{class:'ic','aria-hidden':'true'},'👶'),
        el('span',{class:'nm'},'还没有记录'));
    }
    return el('div',{class:'last'+(pop?' pop':'')},head,main,stEl);
  }
  function buttons(){
    const sleeping=!!lastSE&&lastSE.type==='sleep';
    return el('div',{class:'btns'},...ORDER.map(function(k){
      const t=TYPES[k];
      return el('button',{type:'button',class:'act act-'+k+((sleeping&&k==='wake')?' hint':''),
        'aria-label':'记录'+t.name+'，现在的时间',onclick:function(){add(k)}},
        el('span',{class:'ic','aria-hidden':'true'},t.icon),
        el('span',{class:'lb'},t.name));
    }));
  }

  if(!inline&&ui.view==='history'){
    root.append(el('div',{class:'baby page'},
      el('div',{class:'page-head'},
        el('button',{type:'button',class:'back',onclick:closeHist,'aria-label':'返回'},'‹ 返回'),
        el('span',{class:'ttl'},'全部记录（'+logs.length+'）')),
      summary(),
      el('div',{class:'scroll'},histList())));
    return;
  }

  const wrap=el('div',{class:'baby'});
  if(inline){
    wrap.append(lastBlock(),
      el('div',{class:'mid'},summary(),el('div',{class:'scroll'},histList())),
      buttons());
  }else{
    wrap.append(lastBlock(),buttons());
  }
  root.append(wrap);

  const timer=setInterval(function(){
    const n=Date.now();
    if(!ui.err&&last)agoEl.textContent=fmtAgo(n-last.ts);
    stEl.textContent=statusText();
  },20000);
  return function(){clearInterval(timer)};
}

